// ===== THEMES =====
const THEMES: Record<string, {name:string;bg:string;card:string;accent:string;text:string;sub:string;bL:string;bD:string}> = {
  classic: {name:'Classic',bg:'#1a1a2e',card:'#16213e',accent:'#FFD700',text:'#FFF',sub:'#888',bL:'#F0D9B5',bD:'#B58863'},
  modern: {name:'Modern',bg:'#121220',card:'#1e2d3d',accent:'#00D9FF',text:'#FFF',sub:'#778',bL:'#EEEED2',bD:'#769656'},
  neon: {name:'Neon',bg:'#0a0a1a',card:'#1a0a2e',accent:'#FF00FF',text:'#FFF',sub:'#888',bL:'#E8E0F0',bD:'#7B61FF'},
  emerald: {name:'Emerald',bg:'#0a1a0f',card:'#0e2e16',accent:'#00FF88',text:'#FFF',sub:'#6a8',bL:'#E0F0E0',bD:'#2D8B4E'},
  diamond: {name:'Golden Diamond',bg:'#1a1520',card:'#2a1a30',accent:'#FFD700',text:'#FFF8E0',sub:'#986',bL:'#FFF0D0',bD:'#C49B3F'},
};
function useT(){const{stats}=useLocalStore();return THEMES[stats.theme]||THEMES.classic;}

// ===== 9-MONTH CYCLE =====
function getSeasonalCycle(){const C=9*30*24*60*60*1000;const cy=Math.floor(Date.now()/C);const names=['Ice Storm','Spring Tactics','Summer Blitz','Autumn Endgame','Midnight Mode'];const s=[];for(let i=0;i<5;i++)s.push(names[(cy+i)%names.length]);return{cycle:cy,seasons:s,seed:cy*31337};}
function seededShuffle(arr:any[],seed:number){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=((seed*(i+1)*16807)%2147483647)%((i+1)||1);[a[i],a[j]]=[a[j],a[i]];}return a;}

// ===== CONFETTI =====
function fireConfetti(){if(Platform.OS!=='web')return;const c=document.createElement('div');c.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;pointer-events:none;z-index:9999;overflow:hidden;';document.body.appendChild(c);const st=document.createElement('style');st.textContent='@keyframes cfall{0%{transform:translateY(-10px) rotate(0);opacity:1}100%{transform:translateY(100vh) rotate(720deg);opacity:0}}';document.head.appendChild(st);const cols=['#FFD700','#FF6B35','#2ECC71','#00D9FF','#E74C3C','#9B59B6'];for(let i=0;i<60;i++){const e=document.createElement('div');e.style.cssText=`position:absolute;left:${Math.random()*100}%;top:-10px;width:${5+Math.random()*7}px;height:${5+Math.random()*7}px;background:${cols[i%6]};border-radius:${Math.random()>0.5?'50%':'2px'};animation:cfall ${1+Math.random()*1.5}s ease-in forwards;animation-delay:${Math.random()*0.6}s;`;c.appendChild(e);}setTimeout(()=>{try{document.body.removeChild(c);document.head.removeChild(st);}catch(e){}},3500);}

// ===== SCREEN SHAKE =====
function fireShake(){if(Platform.OS!=='web')return;const r=document.getElementById('root');if(!r)return;r.style.animation='none';r.offsetHeight;r.style.animation='ttshake 0.25s ease';}

// ===== GIFT CODE GEN =====
function genGiftCode(){const c='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let r='TT-';for(let i=0;i<8;i++)r+=c[Math.floor(Math.random()*c.length)];return r;}

const AI_LEVELS=[{key:'beginner',name:'Beginner',desc:'Casual play',icon:'leaf',color:'#2ECC71'},{key:'intermediate',name:'Intermediate',desc:'Basic strategy',icon:'fitness',color:'#3498DB'},{key:'advanced',name:'Advanced',desc:'Tactical (D8)',icon:'flash',color:'#F39C12'},{key:'master',name:'Master',desc:'Positional (D14)',icon:'trophy',color:'#E67E22'},{key:'beyondmaster',name:'Beyond Master',desc:'Super GM (D20)',icon:'diamond',color:'#9B59B6'},{key:'lethal',name:'LETHAL',desc:'Beyond GM (D30+)',icon:'skull',color:'#E74C3C'}];
