const CATS=[{key:'all',name:'All'},{key:'open_game',name:'Open'},{key:'semi_open',name:'Semi-Open'},{key:'closed_game',name:'Closed'},{key:'indian_defense',name:'Indian'},{key:'flank',name:'Flank'},{key:'gambit',name:'Gambits'}];
