// ===== LEGEND GAME =====
function LegendGameScreen({game,onBack}:{game:any;onBack:()=>void}){const t=useT();const chessRef=useRef(new Chess(game.fen));const[fen,setFen]=useState(game.fen);const[sel,setSel]=useState<string|null>(null);const[valid,setValid]=useState<string[]>([]);const[status,setStatus]=useState<'solving'|'correct'|'wrong'>('solving');const[hint,setHint]=useState(false);const[lastM,setLastM]=useState<{from:string;to:string}|null>(null);const handleSq=useCallback((sq:string)=>{if(status!=='solving')return;const chess=chessRef.current;const pc=chess.get(sq as any);if(pc&&pc.color===chess.turn()){ChessSounds.select();const m=chess.moves({square:sq as any,verbose:true});setSel(sq);setValid(m.map((x:any)=>x.to));}else if(sel&&valid.includes(sq)){const mp=chess.get(sel as any);let promo:string|undefined;if(mp?.type==='p'&&(sq[1]==='8'||sq[1]==='1'))promo='q';try{const mv=chess.move({from:sel as any,to:sq as any,promotion:promo as any});if(mv){const cs=mv.san.replace(/[+#]/g,'');const ct=(game.winningMove||'').replace(/[+#]/g,'');if(cs===ct){fireConfetti();ChessSounds.checkmate();setLastM({from:sel,to:sq});setFen(chess.fen());setStatus('correct');setSel(null);setValid([]);let idx=0;const pn=()=>{if(!game.nextMoves||idx>=game.nextMoves.length)return;setTimeout(()=>{try{chess.move(game.nextMoves[idx]);setFen(chess.fen());}catch(e){}idx++;pn();},800);};pn();}else{chess.undo();ChessSounds.invalid();setStatus('wrong');setSel(null);setValid([]);}}}catch(e){setSel(null);setValid([]);}}else{setSel(null);setValid([]);};},[sel,valid,status,game]);const handleRetry=()=>{chessRef.current.load(game.fen);setFen(game.fen);setSel(null);setValid([]);setStatus('solving');setHint(false);setLastM(null);};return(<SafeAreaView style={[styles.screen,{backgroundColor:t.bg}]}><View style={styles.gameHeader}><TouchableOpacity onPress={onBack} style={{padding:8}}><Ionicons name="arrow-back" size={24} color={t.text}/></TouchableOpacity><View style={{flex:1,alignItems:'center'}}><Text style={[styles.cardTitle,{color:t.text}]}>{game.champion} vs {game.opponent}</Text><Text style={{color:t.sub,fontSize:12}}>{game.event} {game.year}</Text></View><TouchableOpacity onPress={()=>setHint(!hint)} style={{padding:8}}><Ionicons name="help-circle" size={24} color={t.accent}/></TouchableOpacity></View>{hint&&<View style={{backgroundColor:'rgba(255,215,0,0.1)',marginHorizontal:16,padding:12,borderRadius:12,marginBottom:8}}><Text style={{color:t.accent,fontWeight:'600'}}>Hint: {(game.theme||'').replace(/_/g,' ')}</Text></View>}<View style={{alignItems:'center',paddingVertical:6}}><Text style={{fontSize:16,fontWeight:'600',color:status==='correct'?'#2ECC71':status==='wrong'?'#E74C3C':t.text}}>{status==='solving'?'Find the winning move!':status==='correct'?'Brilliant!':'Not quite!'}</Text></View><View style={{alignItems:'center',paddingHorizontal:16}}><ChessBoard chess={chessRef.current} selectedSquare={sel} validMoves={valid} onSquarePress={handleSq} disabled={status==='correct'} lastMove={lastM} boardLight={t.bL} boardDark={t.bD}/></View>{status==='correct'&&<View style={{margin:16,backgroundColor:'rgba(46,204,113,0.15)',padding:16,borderRadius:12,borderWidth:1,borderColor:'rgba(46,204,113,0.3)'}}><View style={{flexDirection:'row',alignItems:'center',marginBottom:8}}><Ionicons name="checkmark-circle" size={24} color="#2ECC71"/><Text style={{color:'#2ECC71',fontSize:18,fontWeight:'bold',marginLeft:8}}>{game.winningMove}!</Text></View><Text style={{color:'#CCC',fontSize:14,lineHeight:20}}>{game.description}</Text></View>}{status==='wrong'&&<View style={{margin:16,backgroundColor:'rgba(231,76,60,0.15)',padding:16,borderRadius:12,borderWidth:1,borderColor:'rgba(231,76,60,0.3)'}}><Text style={{color:'#E74C3C',fontWeight:'600',marginBottom:4}}>Think like {game.champion}!</Text><Text style={{color:'#888',fontSize:13}}>Theme: {(game.theme||'').replace(/_/g,' ')}</Text></View>}<View style={{flexDirection:'row',padding:16,gap:12,marginTop:'auto' as any}}>{(status==='wrong'||status==='correct')&&<TouchableOpacity style={[styles.btn,{backgroundColor:t.card}]} onPress={handleRetry}><Ionicons name="refresh" size={20} color={t.text}/><Text style={[styles.btnTxt,{color:t.text}]}>Retry</Text></TouchableOpacity>}{status==='correct'&&<TouchableOpacity style={[styles.btn,{backgroundColor:t.accent}]} onPress={onBack}><Ionicons name="arrow-forward" size={20} color="#1a1a2e"/><Text style={[styles.btnTxt,{color:'#1a1a2e'}]}>Next</Text></TouchableOpacity>}</View></SafeAreaView>);}

