function GameScreen({mode,aiLevel,onBack}:{mode:GameMode;aiLevel:string;onBack:()=>void}){const{incrementGames}=useLocalStore();const t=useT();const[chess]=useState(()=>new Chess());const[fen,setFen]=useState(()=>new Chess().fen());const[sel,setSel]=useState<string|null>(null);const[valid,setValid]=useState<string[]>([]);const[isTurn,setIsTurn]=useState(true);const[gs,setGs]=useState<'playing'|'checkmate'|'draw'>('playing');const[hist,setHist]=useState<string[]>([]);const[result,setResult]=useState('');const[info,setInfo]=useState('');const[lastM,setLastM]=useState<{from:string;to:string}|null>(null);const mpRef=useRef<string[]>([]);const engReady=useRef(false);
useEffect(()=>{ChessSounds.init();ChessSounds.gameStart();if(Platform.OS==='web'){setTimeout(()=>{initEngine().then(()=>{engReady.current=true;});},50);}return()=>{clearTranspositionTable();};},[]);
useEffect(()=>{if(mode==='computer'&&!isTurn&&gs==='playing'){let cancel=false;const doAI=async()=>{setInfo('Thinking...');let moved=false;if(Platform.OS==='web'&&engReady.current){try{const r=await searchMove(chess.fen(),aiLevel,mpRef.current);if(cancel)return;if(r.san){chess.move(r.san);moved=true;setInfo(r.isBook?'Book move':`Depth ${r.depth} | ${(r.nodes||0).toLocaleString()} nodes`);}else if(r.from&&r.to){chess.move({from:r.from as any,to:r.to as any,promotion:r.promotion as any});moved=true;setInfo(r.isBook?'Book move':`Depth ${r.depth}`);}}catch(e){}}if(!moved){const ai=getBestMove(chess,aiLevel as any);if(ai&&!cancel){chess.move(ai);moved=true;setInfo('');}}if(moved&&!cancel){mpRef.current=chess.history();const lm=chess.history({verbose:true});const last=lm[lm.length-1];if(last)setLastM({from:last.from,to:last.to});if(chess.isCheckmate()){fireConfetti();ChessSounds.checkmate();}else if(chess.isCheck()){ChessSounds.check();}else{if(last&&last.captured)fireShake();ChessSounds.move();}doUpdate();setIsTurn(true);}};const tm=setTimeout(doAI,300);return()=>{cancel=true;clearTimeout(tm);};}},[isTurn,gs,mode]);
const doUpdate=useCallback(()=>{setFen(chess.fen());setSel(null);setValid([]);setHist(chess.history());if(chess.isCheckmate()){setGs('checkmate');const w=chess.turn()==='w'?'Black':'White';const won=mode==='computer'?chess.turn()==='b':false;incrementGames(won);setResult(`Checkmate! ${w} wins!`);if(mode==='computer')reportGameResult(won?'loss':'win',chess.history());}else if(chess.isDraw()||chess.isStalemate()){setGs('draw');incrementGames(false);setResult('Draw!');ChessSounds.draw();if(mode==='computer')reportGameResult('draw',chess.history());}},[chess,mode]);
const handleSq=useCallback((sq:string)=>{if(gs!=='playing')return;if(mode==='computer'&&!isTurn)return;const pc=chess.get(sq as any);const turn=chess.turn();if(pc&&pc.color===turn){ChessSounds.select();const m=chess.moves({square:sq as any,verbose:true});setSel(sq);setValid(m.map((x:any)=>x.to));}else if(sel&&valid.includes(sq)){const tp=chess.get(sq as any);const mp=chess.get(sel as any);let promo:string|undefined;if(mp?.type==='p'&&(sq[1]==='8'||sq[1]==='1'))promo='q';try{const mv=chess.move({from:sel as any,to:sq as any,promotion:promo as any});if(mv){mpRef.current=chess.history();setLastM({from:sel,to:sq});if(chess.isCheckmate()){fireConfetti();ChessSounds.checkmate();}else if(chess.isDraw()||chess.isStalemate()){ChessSounds.draw();}else if(chess.isCheck())ChessSounds.check();else if(tp){fireShake();ChessSounds.capture();}else ChessSounds.move();doUpdate();if(mode==='computer')setIsTurn(false);}}catch(e){ChessSounds.invalid();}}else{setSel(null);setValid([]);}},[chess,sel,valid,gs,mode,isTurn,doUpdate]);
const newGame=()=>{chess.reset();setFen(chess.fen());setSel(null);setValid([]);setIsTurn(true);setGs('playing');setHist([]);setResult('');setInfo('');setLastM(null);mpRef.current=[];clearTranspositionTable();ChessSounds.gameStart();};
const resign=()=>{if(mode==='computer')reportGameResult('loss',chess.history());incrementGames(false);onBack();};
const turnText=gs!=='playing'?result:mode==='computer'?(isTurn?'Your turn':'AI thinking...'):chess.turn()==='w'?"White's turn":"Black's turn";
return(<SafeAreaView style={[styles.screen,{backgroundColor:t.bg}]}><View style={styles.gameHeader}><TouchableOpacity onPress={onBack} style={{padding:8}}><Ionicons name="arrow-back" size={24} color={t.text}/></TouchableOpacity><View style={{flex:1,alignItems:'center'}}><Text style={[styles.cardTitle,{color:t.text}]}>{mode==='computer'?`vs AI (${aiLevel})`:'Local Game'}</Text><Text style={{color:t.accent,fontSize:13,marginTop:2}}>{turnText}</Text>{info?<Text style={{color:t.sub,fontSize:11,marginTop:1}}>{info}</Text>:null}</View><TouchableOpacity onPress={resign} style={{padding:8}}><Ionicons name="flag" size={24} color="#E74C3C"/></TouchableOpacity></View>{chess.isCheck()&&gs==='playing'&&<View style={styles.checkBanner}><Ionicons name="warning" size={16} color="#E74C3C"/><Text style={{color:'#E74C3C',fontWeight:'bold',marginLeft:8}}>Check!</Text></View>}<View style={{alignItems:'center',paddingHorizontal:16}}><ChessBoard chess={chess} selectedSquare={sel} validMoves={valid} onSquarePress={handleSq} disabled={gs!=='playing'||(mode==='computer'&&!isTurn)} lastMove={lastM} boardLight={t.bL} boardDark={t.bD}/>{mode==='computer'&&!isTurn&&gs==='playing'&&<View style={{position:'absolute',top:10,right:26}}><ActivityIndicator size="small" color={t.accent}/></View>}</View>{result?<View style={{alignItems:'center',marginTop:16}}><Text style={{color:t.accent,fontSize:20,fontWeight:'bold'}}>{result}</Text></View>:null}<View style={{flex:1,marginHorizontal:16,marginTop:12,backgroundColor:t.card,borderRadius:12,padding:12}}><Text style={{fontSize:13,color:t.sub,marginBottom:6}}>Moves</Text><ScrollView><View style={{flexDirection:'row',flexWrap:'wrap'}}>{hist.map((m,i)=><Text key={i} style={{fontSize:14,color:t.text}}>{i%2===0?`${Math.floor(i/2)+1}. `:'  '}{m} </Text>)}</View></ScrollView></View><View style={{flexDirection:'row',padding:16,gap:12}}><TouchableOpacity style={[styles.btn,{backgroundColor:t.card}]} onPress={newGame}><Ionicons name="refresh" size={20} color={t.text}/><Text style={[styles.btnTxt,{color:t.text}]}>New Game</Text></TouchableOpacity><TouchableOpacity style={[styles.btn,{backgroundColor:'rgba(231,76,60,0.1)'}]} onPress={resign}><Ionicons name="flag" size={20} color="#E74C3C"/><Text style={[styles.btnTxt,{color:'#E74C3C'}]}>Resign</Text></TouchableOpacity></View></SafeAreaView>);}

// ===== PUZZLE =====
function PuzzleScreen({difficulty,onBack}:{difficulty:string;onBack:()=>void}){const{incrementPuzzles}=useLocalStore();const t=useT();const[puzzle,setPuzzle]=useState<any>(null);const[chess,setChess]=useState<Chess|null>(null);const[fen,setFen]=useState('');const[sel,setSel]=useState<string|null>(null);const[valid,setValid]=useState<string[]>([]);const[status,setStatus]=useState<'loading'|'solving'|'completed'|'incorrect'>('loading');const[mi,setMi]=useState(0);const[opp,setOpp]=useState(false);const[lastM,setLastM]=useState<{from:string;to:string}|null>(null);
const loadP=useCallback(()=>{let pool=ALL_PUZZLES.filter((p:any)=>p.difficulty===difficulty);if(difficulty==='impossible'){const{seed}=getSeasonalCycle();pool=seededShuffle(pool,seed);}if(!pool.length)return;const p=pool[Math.floor(Math.random()*pool.length)];setPuzzle(p);const c=new Chess(p.fen);setChess(c);setFen(p.fen);setMi(0);setStatus('solving');setSel(null);setValid([]);setLastM(null);},[difficulty]);useEffect(()=>{loadP();},[difficulty]);
const handleSq=useCallback((sq:string)=>{if(!chess||!puzzle||status!=='solving'||opp)return;const pc=chess.get(sq as any);if(pc&&pc.color===chess.turn()){const m=chess.moves({square:sq as any,verbose:true});setSel(sq);setValid(m.map((x:any)=>x.to));}else if(sel&&valid.includes(sq)){const mp=chess.get(sel as any);let promo:string|undefined;if(mp?.type==='p'&&(sq[1]==='8'||sq[1]==='1'))promo='q';try{const mv=chess.move({from:sel as any,to:sq as any,promotion:promo as any});if(mv){const exp=puzzle.solution[mi];if(mv.san===exp||mv.lan===exp||`${mv.from}${mv.to}`===exp||mv.san.replace(/[+#]/g,'')===exp.replace(/[+#]/g,'')){setLastM({from:sel,to:sq});setFen(chess.fen());setSel(null);setValid([]);const ni=mi+1;setMi(ni);if(ni>=puzzle.solution.length){fireConfetti();setStatus('completed');incrementPuzzles(15);}else{setOpp(true);setTimeout(()=>{try{const om=chess.move(puzzle.solution[ni]);if(om)setLastM({from:om.from,to:om.to});setFen(chess.fen());setMi(ni+1);}catch(e){}setOpp(false);},500);}}else{chess.undo();setSel(null);setValid([]);setStatus('incorrect');incrementPuzzles(-10);}}}catch(e){}}else{setSel(null);setValid([]);}},[chess,puzzle,sel,valid,status,mi,opp]);
const diffColor=difficulty==='easy'?'#2ECC71':difficulty==='medium'?'#F39C12':difficulty==='hard'?'#E74C3C':'#9B59B6';return(<SafeAreaView style={[styles.screen,{backgroundColor:t.bg}]}><View style={styles.gameHeader}><TouchableOpacity onPress={onBack} style={{padding:8}}><Ionicons name="arrow-back" size={24} color={t.text}/></TouchableOpacity><View style={{flex:1,flexDirection:'row',alignItems:'center',justifyContent:'center'}}><Text style={[styles.cardTitle,{color:t.text}]}>Puzzle</Text><View style={[styles.diffBadge,{backgroundColor:`${diffColor}20`,marginLeft:8}]}><Text style={{color:diffColor,fontSize:11,fontWeight:'bold'}}>{difficulty.toUpperCase()}</Text></View></View><View style={{backgroundColor:'rgba(255,215,0,0.2)',paddingVertical:4,paddingHorizontal:10,borderRadius:8}}><Text style={{color:t.accent,fontWeight:'bold',fontSize:13}}>{puzzle?.rating||'...'}</Text></View></View>{puzzle&&<View style={{alignItems:'center',paddingVertical:6}}><Text style={{fontSize:15,fontWeight:'600',color:t.text}}>{chess?.turn()==='w'?'White':'Black'} to move</Text>{puzzle.theme&&<Text style={{fontSize:12,color:t.sub,marginTop:2,textTransform:'capitalize'}}>Theme: {puzzle.theme.replace(/_/g,' ')}</Text>}</View>}<View style={{alignItems:'center',paddingHorizontal:16,paddingVertical:12}}>{status==='loading'?<View style={{height:300,justifyContent:'center'}}><ActivityIndicator size="large" color={t.accent}/></View>:chess&&<ChessBoard chess={chess} selectedSquare={sel} validMoves={valid} onSquarePress={handleSq} disabled={status!=='solving'||opp} lastMove={lastM} boardLight={t.bL} boardDark={t.bD}/>}{opp&&<View style={{position:'absolute',top:20,right:26}}><ActivityIndicator size="small" color={t.accent}/></View>}</View>{status==='completed'&&<View style={[styles.statusBanner,{backgroundColor:'rgba(46,204,113,0.2)'}]}><Ionicons name="checkmark-circle" size={24} color="#2ECC71"/><Text style={{color:'#2ECC71',fontSize:18,fontWeight:'bold',marginLeft:8}}>Solved!</Text></View>}{status==='incorrect'&&<><View style={[styles.statusBanner,{backgroundColor:'rgba(231,76,60,0.2)'}]}><Ionicons name="close-circle" size={24} color="#E74C3C"/><Text style={{color:'#E74C3C',fontSize:18,fontWeight:'bold',marginLeft:8}}>Incorrect!</Text></View><View style={{alignItems:'center',marginBottom:8}}><Text style={{color:t.sub,fontSize:12}}>Solution:</Text><Text style={{color:t.accent,fontSize:16,fontWeight:'bold',marginTop:4}}>{puzzle?.solution[0]}</Text></View></>}<View style={{flexDirection:'row',padding:16,gap:12,marginTop:'auto' as any}}>{(status==='completed'||status==='incorrect')&&<><TouchableOpacity style={[styles.btn,{backgroundColor:t.card}]} onPress={()=>{if(!puzzle)return;const c2=new Chess(puzzle.fen);setChess(c2);setFen(puzzle.fen);setMi(0);setStatus('solving');setSel(null);setValid([]);setLastM(null);}}><Ionicons name="refresh" size={20} color={t.text}/><Text style={[styles.btnTxt,{color:t.text}]}>Retry</Text></TouchableOpacity><TouchableOpacity style={[styles.btn,{backgroundColor:t.accent}]} onPress={loadP}><Ionicons name="arrow-forward" size={20} color="#1a1a2e"/><Text style={[styles.btnTxt,{color:'#1a1a2e'}]}>Next</Text></TouchableOpacity></>}{status==='solving'&&<TouchableOpacity style={[styles.btn,{backgroundColor:t.card}]} onPress={loadP}><Ionicons name="shuffle" size={20} color={t.text}/><Text style={[styles.btnTxt,{color:t.text}]}>Skip</Text></TouchableOpacity>}</View></SafeAreaView>);}

const styles=StyleSheet.create({appContainer:{flex:1,backgroundColor:'#1a1a2e'},screen:{flex:1,backgroundColor:'#1a1a2e'},pad20:{padding:20},h1:{fontSize:26,fontWeight:'bold',color:'#FFF'},h2:{fontSize:18,fontWeight:'600',color:'#FFF',marginBottom:14},sub:{fontSize:14,color:'#888',marginTop:4,marginBottom:16},headerRow:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',marginBottom:24},badge:{flexDirection:'row',alignItems:'center',backgroundColor:'rgba(255,215,0,0.1)',paddingHorizontal:12,paddingVertical:5,borderRadius:20},badgeText:{color:'#FFD700',fontSize:11,fontWeight:'bold',marginLeft:4},card:{flexDirection:'row',alignItems:'center',backgroundColor:'#16213e',borderRadius:16,padding:16,marginBottom:12},cardIcon:{width:54,height:54,borderRadius:27,alignItems:'center',justifyContent:'center'},cardBody:{flex:1,marginLeft:14},cardTitle:{fontSize:17,fontWeight:'600',color:'#FFF'},cardSub:{fontSize:13,color:'#888',marginTop:3},statsRow:{flexDirection:'row',justifyContent:'space-between'},statBox:{flex:1,alignItems:'center',backgroundColor:'#16213e',padding:14,borderRadius:12,marginHorizontal:3},statVal:{fontSize:22,fontWeight:'bold',color:'#FFD700'},statLbl:{fontSize:11,color:'#888',marginTop:4},statsCard:{flexDirection:'row',alignItems:'center',backgroundColor:'#16213e',borderRadius:16,padding:20,marginBottom:24},tabBar:{flexDirection:'row',backgroundColor:'#16213e',borderTopWidth:1,borderTopColor:'#222',paddingBottom:Platform.OS==='ios'?20:8,paddingTop:8},tabButton:{flex:1,alignItems:'center',paddingVertical:4},tabLabel:{fontSize:11,color:'#555',marginTop:3},gameHeader:{flexDirection:'row',alignItems:'center',paddingHorizontal:12,paddingVertical:10},checkBanner:{flexDirection:'row',alignItems:'center',justifyContent:'center',backgroundColor:'rgba(231,76,60,0.2)',paddingVertical:6,marginHorizontal:16,borderRadius:8,marginBottom:6},btn:{flex:1,flexDirection:'row',alignItems:'center',justifyContent:'center',backgroundColor:'#16213e',paddingVertical:14,borderRadius:12},btnTxt:{fontSize:16,color:'#FFF',marginLeft:8},modalBg:{flex:1,backgroundColor:'rgba(0,0,0,0.8)',justifyContent:'center',alignItems:'center',padding:20},modal:{backgroundColor:'#16213e',borderRadius:20,padding:24,width:'100%',maxWidth:400},modalTitle:{fontSize:22,fontWeight:'bold',color:'#FFF',textAlign:'center',marginBottom:20},modalClose:{marginTop:8,padding:16,alignItems:'center'},aiOpt:{flexDirection:'row',alignItems:'center',backgroundColor:'rgba(255,255,255,0.05)',padding:14,borderRadius:12,marginBottom:10},aiOptIcon:{width:44,height:44,borderRadius:22,backgroundColor:'rgba(255,215,0,0.1)',alignItems:'center',justifyContent:'center'},aiOptName:{fontSize:16,fontWeight:'600',color:'#FFF',marginLeft:12},chip:{backgroundColor:'#16213e',paddingVertical:8,paddingHorizontal:14,borderRadius:20,marginRight:8},chipText:{color:'#888',fontSize:13},openingCard:{backgroundColor:'#16213e',borderRadius:16,padding:16,marginBottom:10},diffBadge:{paddingVertical:3,paddingHorizontal:8,borderRadius:8},movesBox:{flexDirection:'row',backgroundColor:'rgba(255,215,0,0.1)',padding:8,borderRadius:8},statusBanner:{flexDirection:'row',alignItems:'center',justifyContent:'center',paddingVertical:12,marginHorizontal:16,borderRadius:12,marginBottom:10}});
